using System.Collections;
using OcctSharp.AssemblyDiagnostics;
using OcctSharp.CopiedCollections;
using OcctSharp.Generated;
using OcctSharp.ModelingWorkspaces;
using OcctSharp.Tests.Shared;
using OcctSharp.Values;
namespace OcctSharp.Runtime.Tests;
public sealed class AssemblyDiagnosticTests {
 [Fact]public void CopiedPcurveWireFaceRepairAndActualFileReadback()=>BatchBAAssemblyWorkflow.Run();
 [Fact]public void TypedCurveBuilderCopiesInputsAndExplicitEndpoints(){using var curve=BatchAWGeometryWorkflow.Section(0);using var result=AssemblyWorkflows.Edge(curve,0,1,new GpPoint(0,0,0),new GpPoint(3,0,0));Assert.True(result.IsDone);Assert.True(result.Has3dCurve);using var a=result.Shape;using var b=result.Shape;curve.Dispose();result.Dispose();Assert.True(a.IsValid);Assert.True(b.IsValid);Assert.Equal(2,a.CountSubShapes(ShapeKind.Vertex));Assert.Null(result.FailureInputIndex);Assert.Throws<ObjectDisposedException>(()=>result.Shape);}
 [Fact]public void FailedEndpointAndRangeDoNotPublishPartialEdges(){using var curve=BatchAWGeometryWorkflow.Section(0);using var invalid=AssemblyWorkflows.Edge(curve,0,1,new GpPoint(0,1,0),new GpPoint(3,0,0));Assert.False(invalid.IsDone);Assert.NotEqual(0,invalid.Error);Assert.Throws<InvalidOperationException>(()=>invalid.Shape);Assert.ThrowsAny<Exception>(()=>AssemblyWorkflows.Edge(curve,-1,1));Assert.ThrowsAny<Exception>(()=>AssemblyWorkflows.Edge(curve,0,0));Assert.Throws<ArgumentException>(()=>AssemblyWorkflows.Edge(curve,0,1,new GpPoint(0,0,0)));}
 [Theory][InlineData(0)][InlineData(1)]public void MixedEdgesAndWiresAssembleWithNativeClosedAndConnectionDiagnostics(int backend){using var a=ModelingBuilders.Edge(new(0,0,0),new(1,0,0));using var b=ModelingBuilders.Edge(new(1,0,0),new(1,1,0));using var c=ModelingBuilders.Edge(new(1,1,0),new(0,0,0));using var sa=a.Shape;using var sb=b.Shape;using var sc=c.Shape;using var first=OwnedShapeSet.Create(sa,sb);using var sub=AssemblyWorkflows.Wire(first,backend);Assert.True(sub.IsDone);using var wire=sub.Shape;using var mixed=OwnedShapeSet.Create(wire,sc);using var completed=AssemblyWorkflows.Wire(mixed,backend);Assert.True(completed.IsDone);Assert.True(completed.IsClosed);Assert.Equal(3,completed.EdgeCount);using var copied=completed.Shape;Assert.True(copied.IsValid);Assert.Equal(0,AssemblyWorkflows.Validate(copied,parallel:true).InvalidSubshapeCount);}
 [Theory][InlineData(0)][InlineData(1)]public void WireDisconnectionAndEmptyInputsRetainErrorsWithoutPartialTopology(int backend){using var a=ModelingBuilders.Edge(new(0,0,0),new(1,0,0));using var b=ModelingBuilders.Edge(new(5,0,0),new(6,0,0));using var sa=a.Shape;using var sb=b.Shape;using var input=OwnedShapeSet.Create(sa,sb);using var result=AssemblyWorkflows.Wire(input,backend);Assert.False(result.IsDone);Assert.Equal(1,result.FailureInputIndex);Assert.Throws<InvalidOperationException>(()=>result.Shape);using var empty=OwnedShapeSet.Create();using var unfinished=AssemblyWorkflows.Wire(empty,backend);Assert.False(unfinished.IsDone);Assert.NotEqual(0,unfinished.Error);}
 [Fact]public void SurfaceBoundaryRejectsAmbiguityDomainAndDegenerateSegments(){using var surface=BatchBAAssemblyWorkflow.Surface();Assert.ThrowsAny<Exception>(()=>AssemblyWorkflows.WireOnSurface(surface,new Point2d[]{new(0,0),new(1,0),new(1,1)},makeFace:true));Assert.ThrowsAny<Exception>(()=>AssemblyWorkflows.WireOnSurface(surface,new Point2d[]{new(0,0),new(0,0)},makeFace:false));Assert.ThrowsAny<Exception>(()=>AssemblyWorkflows.WireOnSurface(surface,new Point2d[]{new(0,0),new(2,0)},makeFace:false));using var open=AssemblyWorkflows.WireOnSurface(surface,new Point2d[]{new(0,0),new(1,0)},makeFace:false);Assert.True(open.IsDone);Assert.False(open.IsClosed);Assert.ThrowsAny<Exception>(()=>open.Face(surface));}
 [Fact]public void WireAreaIndicesBelongToTheExactCopiedFace(){using var surface=BatchBAAssemblyWorkflow.Surface();using var result=AssemblyWorkflows.WireOnSurface(surface,BatchBAAssemblyWorkflow.Boundary);using var face=result.Shape;Assert.ThrowsAny<Exception>(()=>AssemblyWorkflows.WireArea(face,-1));Assert.ThrowsAny<Exception>(()=>AssemblyWorkflows.WireArea(face,1));using var wire=result.GetRelatedShape(1)!;Assert.ThrowsAny<Exception>(()=>AssemblyWorkflows.WireArea(wire));var info=AssemblyWorkflows.Validate(face,exact:false,parallel:true);Assert.False(info.UsesExactMethod);Assert.True(info.IsParallel);}
 [Fact]public void SurfaceBoundaryLazyEnumerationIsBoundedAndDisposed(){using var surface=BatchBAAssemblyWorkflow.Surface();var points=new Endless();Assert.Throws<ArgumentOutOfRangeException>(()=>AssemblyWorkflows.WireOnSurface(surface,points));Assert.Equal(4098,points.Yielded);Assert.True(points.Disposed);}
 [Fact]public void ConstructionStagesIdentifyErrorsAndInputWireBudgetIsCheckedBeforeAssembly(){using var surface=BatchBAAssemblyWorkflow.Surface();using var face=AssemblyWorkflows.WireOnSurface(surface,BatchBAAssemblyWorkflow.Boundary);Assert.Equal(AssemblyStage.Face,face.Stage);using var a=ModelingBuilders.Edge(new(0,0,0),new(1,0,0));using var b=ModelingBuilders.Edge(new(1,0,0),new(2,0,0));using var sa=a.Shape;using var sb=b.Shape;using var input=OwnedShapeSet.Create(sa,sb);using var result=AssemblyWorkflows.Wire(input);Assert.Equal(AssemblyStage.Wire,result.Stage);using var wire=result.Shape;using var huge=OwnedShapeSet.Create(Enumerable.Repeat(wire,2049).ToArray());Assert.ThrowsAny<Exception>(()=>AssemblyWorkflows.Wire(huge));using var curve=BatchAWGeometryWorkflow.Section(0);using var edge=AssemblyWorkflows.Edge(curve,0,1);Assert.Equal(AssemblyStage.Edge,edge.Stage);}
 [Fact]public void ReversedBoundaryIsExplicitlyClosedAndValid(){using var surface=BatchBAAssemblyWorkflow.Surface();using var face=AssemblyWorkflows.WireOnSurface(surface,BatchBAAssemblyWorkflow.Boundary.Reverse());Assert.True(face.IsDone);using var shape=face.Shape;Assert.True(shape.IsValid);Assert.Equal(4,face.EdgeCount);}
 [Fact]public void ConcurrentPrivateBuildersKeepIndependentResults(){Parallel.For(0,12,_=>{using var surface=BatchBAAssemblyWorkflow.Surface();using var result=AssemblyWorkflows.WireOnSurface(surface,BatchBAAssemblyWorkflow.Boundary);using var shape=result.Shape;Assert.True(shape.IsValid);Assert.Equal(4,result.EdgeCount);});}
 sealed class Endless:IEnumerable<Point2d>{public int Yielded;public bool Disposed;public IEnumerator<Point2d> GetEnumerator(){try{while(true){++Yielded;yield return new(0,0);}}finally{Disposed=true;}}IEnumerator IEnumerable.GetEnumerator()=>GetEnumerator();}
}
